    InvalidRegister;
    InvalidImmediate;
    InvalidCondition;
    MisalignedOffset;
    BranchOutOfRange;
    DuplicateLabel(string);
    UndefinedLabel(string);
    InvalidPatch;
}

kiso/aot/lower.signature:
koukai sentaku LowerError {
    UnsupportedConstant;
    UnsupportedOpcode(int64);
    UnsupportedClosure;
    InvalidFunction;
    InvalidOperand(int64);
    FrameTooLarge;
    EncodeFailure;
    UnsafeType(int64);
    UnsupportedNative(int64);
}

koukai kata LowerResult {
    words: []uint32;
    constants: []uint8;
    patches: []macho.AddressPatch;
    globals: int64;
    error: LowerError?;
}

kiso/aot/lower/types.signature:
koukai kata TypeArena {
    parent: []int64;
    kind: []int64;
    nullable: []bool;
    struct_arity: []int64;
    struct_exact: []bool;
    fields: [][]int64;
    array_width: []int64;
}

koukai kata TypeBlock {
    data: []uint8;
    function_id: int64;
    entry: [][]int64;
    reachable: []bool;
}

koukai kata TypeAnalysis {
    arena: TypeArena;
    globals: []int64;
    locals: [][]int64;
    returns: []int64;
    blocks: []TypeBlock;
    error_detail: int64;
}

kiso/aot/macho.signature:
koukai sentaku MachOError {
    EmptyText;
