kiso/encoding/mochi.signature:
koukai sentaku DecodeErrorKind {
    Truncated;
    InvalidMagic;
    UnsupportedVersion;
    LimitExceeded;
    InvalidConstant;
    InvalidUtf8;
    InvalidFunction;
    InvalidInstruction;
    InvalidIndex;
    InvalidJump;
    TrailingData;
    IoFailure;
}

koukai kata Function {
    id: int64;
    name: string;
    name_bytes: []uint8;
    parameter_count: int64;
    local_count: int64;
    returns_value: bool;
    captures: []Capture;
    instructions: []uint8;
}

koukai kata File {
    version: int64;
    constants: []Constant;
    global_count: int64;
    instructions: []uint8;
    functions: []Function;
}

koukai kata Summary {
    version: int64;
    constants: int64;
    functions: int64;
    globals: int64;
    instruction_bytes: int64;
    canonical_size: int64;
}

